// Custom Worker entry: OpenNext's request handler + a Cron Trigger that runs the retention job.
// The `.open-next/worker.js` file is generated by `opennextjs-cloudflare build`.
// @ts-expect-error generated at build time
import { default as handler } from "../.open-next/worker.js";

interface Env {
  CRON_SECRET?: string;
}

export default {
  fetch: handler.fetch,
  async scheduled(_event: unknown, env: Env, ctx: { waitUntil(p: Promise<unknown>): void }) {
    if (!env.CRON_SECRET) return;
    const req = new Request("https://worker.internal/api/cron/cleanup", { headers: { Authorization: `Bearer ${env.CRON_SECRET}` } });
    ctx.waitUntil(handler.fetch(req, env, ctx));
  },
};

// @ts-expect-error generated at build time
export { DOQueueHandler, DOShardedTagCache, BucketCachePurge } from "../.open-next/worker.js";
